# reproduce the aligned component matrices and print them
h,w=len(testgrid),len(testgrid[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if testgrid[r][c] and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); cc=[]
   while q:
    y,x=q.pop();cc.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and testgrid[yy][xx] and (yy,xx) not in seen:seen.add((yy,xx));q.append((yy,xx))
   comps.append(cc)
print([(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co),len(co)) for co in comps])
for co in comps:
 r0=min(r for r,c in co);r1=max(r for r,c in co);c0=min(c for r,c in co);c1=max(c for r,c in co)
 print('bbox',r0,r1,c0,c1)
 for r in range(r0,r1+1):print([testgrid[r][c] for c in range(c0,c1+1)])
